INSERT INTO `cache_render` VALUES ('entity_view:block:cfc_footer:[languages:language_interface]=en:[route]=cfc_pages.home35786c7117b4e38d0f169239752ce71158266ae2f6e4aa230fbbb87bd699c0e3:[theme]=cfc_media_hub:[user.permissions]=479e8a1471396e0255ed12924301d6284dd64c7809ad84c87ec546b78f72f96e',_binary 'a:3:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:6780:\"<div id=\"block-cfc-footer\">\n  \n    \n      <footer class=\"bg-neutral-950 text-white/80 pt-20 pb-10\">\n  <div class=\"max-w-[1440px] mx-auto px-12\">\n\n        <div class=\"mb-14 pb-14 border-b border-white/10\" x-data=\"{ subscribed: false, email: \'\' }\">\n      <div class=\"grid grid-cols-12 gap-12 items-center\">\n        <div class=\"col-span-5\">\n          <div class=\"text-[11px] uppercase tracking-[0.18em] text-[#9F5434] font-bold mb-3\">Newsletter</div>\n          <h2 class=\"tracking-tight text-white mb-3\" style=\"font-size: 28px; font-weight: 600; letter-spacing: -0.02em;\">Stay informed.</h2>\n          <p class=\"text-white/55 leading-relaxed text-[14px]\">Receive CFC Media Hub news, reports and editorial updates directly in your inbox.</p>\n        </div>\n        <div class=\"col-span-7 flex items-center justify-end\">\n          <div x-show=\"subscribed\" x-cloak class=\"flex items-center gap-3 bg-white/[0.06] border border-white/10 rounded-2xl px-6 py-4\">\n            <span class=\"text-[#9F5434] text-lg\">&#10003;</span>\n            <div>\n              <div class=\"text-white text-[14px] font-semibold\">You\'re subscribed.</div>\n              <div class=\"text-white/50 text-[12px]\">Expect updates and reports in your inbox.</div>\n            </div>\n          </div>\n          <form x-show=\"!subscribed\" x-on:submit.prevent=\"subscribed = true\" class=\"flex gap-3 w-full max-w-[500px]\">\n            <label for=\"footer-newsletter-email\" class=\"sr-only\">Email address</label>\n            <input\n              id=\"footer-newsletter-email\"\n              type=\"email\"\n              name=\"email\"\n              x-model=\"email\"\n              required\n              placeholder=\"Enter your email address\"\n              class=\"flex-1 bg-white/[0.06] border border-white/15 rounded-xl px-5 py-3.5 text-[14px] text-white placeholder:text-white/35 focus:outline-none focus:border-white/30 transition-colors\"\n            />\n            <button type=\"submit\" class=\"bg-[#9F5434] hover:bg-[#8A4A2E] text-white px-6 py-3.5 rounded-xl text-[13px] font-semibold transition-colors shrink-0\">\n              Subscribe\n            </button>\n          </form>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"grid grid-cols-12 gap-12 pb-14 border-b border-white/10\">\n      <div class=\"col-span-4\">\n        <a href=\"/\" class=\"mb-6 block\">\n          <img src=\"/themes/custom/cfc_media_hub/images/logo.png\" alt=\"CFC Media Hub\" class=\"h-20 w-auto brightness-0 invert\" />\n        </a>\n        <p class=\"text-[14px] text-white/60 leading-relaxed max-w-[320px]\">\n          CFC Media Hub — workspaces, meeting rooms and a studio for international journalists.\n        </p>\n        <div class=\"mt-6 text-[13px] text-white/50 leading-relaxed\">\n          Located in Casablanca Finance City<br />\n          Main Street – CFC Cube, 2nd Floor<br />\n          Casablanca &middot; Morocco\n        </div>\n      </div>\n\n              <div class=\"col-span-2\">\n          <div class=\"text-[12px] uppercase tracking-wide text-white font-semibold mb-4\">Spaces</div>\n          <ul class=\"space-y-2.5\">\n                          <li>\n                <a href=\"/spaces\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Desk</a>\n              </li>\n                          <li>\n                <a href=\"/spaces\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Meeting Room</a>\n              </li>\n                          <li>\n                <a href=\"/spaces\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Studio</a>\n              </li>\n                      </ul>\n        </div>\n              <div class=\"col-span-2\">\n          <div class=\"text-[12px] uppercase tracking-wide text-white font-semibold mb-4\">Editorial</div>\n          <ul class=\"space-y-2.5\">\n                          <li>\n                <a href=\"/insights\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Press Releases</a>\n              </li>\n                          <li>\n                <a href=\"/insights\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Media Library</a>\n              </li>\n                          <li>\n                <a href=\"/insights\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Insights</a>\n              </li>\n                          <li>\n                <a href=\"/production\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Press kit</a>\n              </li>\n                      </ul>\n        </div>\n              <div class=\"col-span-2\">\n          <div class=\"text-[12px] uppercase tracking-wide text-white font-semibold mb-4\">Production</div>\n          <ul class=\"space-y-2.5\">\n                          <li>\n                <a href=\"/production\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Member Companies</a>\n              </li>\n                          <li>\n                <a href=\"/hub\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">About CFC</a>\n              </li>\n                      </ul>\n        </div>\n              <div class=\"col-span-2\">\n          <div class=\"text-[12px] uppercase tracking-wide text-white font-semibold mb-4\">Support</div>\n          <ul class=\"space-y-2.5\">\n                          <li>\n                <a href=\"mailto:mediahub@cfcma.com\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Contact</a>\n              </li>\n                          <li>\n                <a href=\"/\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">FAQ</a>\n              </li>\n                          <li>\n                <a href=\"/\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Terms</a>\n              </li>\n                          <li>\n                <a href=\"/\" class=\"text-[13px] text-white/60 hover:text-white transition-colors\">Privacy</a>\n              </li>\n                      </ul>\n        </div>\n          </div>\n\n    <div class=\"pt-6 space-y-3\">\n      <div class=\"text-[12px] text-white/35 leading-relaxed max-w-[760px]\">\n        An initiative by CFCA, in partnership with the Région Casablanca-Settat and the Ministry of Youth, Culture and Communication.\n      </div>\n      <div class=\"flex items-center justify-between text-[12px] text-white/45\">\n        <div>&copy; 2026 CFC Media Hub. Operated by Casablanca Finance City Authority.</div>\n        <div class=\"flex items-center gap-6\">\n          <button type=\"button\" class=\"hover:text-white transition-colors\">EN</button>\n          <button type=\"button\" class=\"hover:text-white transition-colors\">FR</button>\n          <button type=\"button\" class=\"hover:text-white transition-colors\">AR</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</footer>\n\n  </div>\n\";}s:9:\"#attached\";a:1:{s:7:\"library\";a:1:{i:0;s:37:\"core/components.cfc_media_hub--footer\";}}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:4:{i:0;s:5:\"route\";i:1;s:28:\"languages:language_interface\";i:2;s:5:\"theme\";i:3;s:16:\"user.permissions\";}s:4:\"tags\";a:5:{i:0;s:17:\"config:block_list\";i:1;s:32:\"config:system.menu.footer-spaces\";i:2;s:35:\"config:system.menu.footer-editorial\";i:3;s:36:\"config:system.menu.footer-production\";i:4;s:33:\"config:system.menu.footer-support\";}s:7:\"max-age\";i:-1;}}',-1,